@pytest.mark.parametrize(
    "api_key, expected_status_code, is_valid_key",
    [
        ("valid_api_key", 200, True),  # Valid API Key, expect success
        ("invalid_api_key_123", 401, False),  # Invalid API Key, expect authorization failure
        (None, 401, False),  # Missing API Key, expect authorization failure
    ]
)
def test_get_inventory(api_client, api_key, expected_status_code, is_valid_key, valid_api_key):
    """
    Test the /store/inventory endpoint with valid, invalid, and missing API keys.
    Also performs schema validation for successful responses.

    Parameters:
    - api_client: The API client fixture.
    - api_key: API key to be used for authentication.
    - expected_status_code: Expected HTTP status code.
    - is_valid_key: Indicates if the API key is valid.
    - valid_api_key: Fixture holding the valid API key.

    """
    # Set API headers for authentication
    headers = {"Authorization": api_key} if api_key else {}

    # Make GET request
    response = api_client.get("/store/inventory", headers=headers)

    # Assert status code
    assert response.status_code == expected_status_code, f"Unexpected status code: {response.status_code}"

    # If the response was successful, validate response schema
    if is_valid_key and response.status_code == 200:
        schema = {
            "type": "object",
            "additionalProperties": {
                "type": "integer",
                "format": "int32"
            }
        }
        try:
            response_data = response.json()
            validate(instance=response_data, schema=schema)
        except json.JSONDecodeError:
            pytest.fail("Failed to decode JSON response.")
        except Exception as e:
            pytest.fail(f"Response schema validation failed: {e}")

        # Ensure all values in the response are non-negative integers
        for key, value in response_data.items():
            assert isinstance(value, int) and value >= 0, f"Invalid inventory value for '{key}': {value}"


